dialog#BrixxDialog {
  font-family: 'Numans', sans-serif;
  top: 50%;
  left: 50%;
  margin: 0px;
  transform: translate(-50%, -50%);
  position: fixed;
  background-color: #f9f9f9;
  border: 1px solid #000;
  border-radius: 3px;
  max-width: 400px;
  width: 90%;
  user-select: none;
  overflow-x: hidden;
