dialog#BrixxDialog::backdrop {
  background-color: rgba(0, 0, 0, 0.8);
}

dialog#BrixxDialog h2,
dialog#BrixxDialog p {
  margin: 5px 0px 0px 0px;
  padding: 0;
  text-align: left;
  width: 100%;
}

dialog#BrixxDialog h2 {
  font-size: 20px;
  font-weight: normal;
  color: white;
}

dialog#BrixxDialog p {
  font-size: 16px;
  color: #555;
  margin-top: 40px;
  margin-bottom: -20px;
  line-height: 1.4;
}

dialog#BrixxDialog input {
  width: 100%;
  height: 35px;
  margin-top: 20px;
  margin-bottom: 20px;
  padding: 6px 6px;
  border: 1px solid #000;
  box-sizing: border-box;
  border-radius: 3px;
  font-size: 16px;
  background-color: whitesmoke;
  color: black;
}
dialog#BrixxDialog input::placeholder {
  font-size: 15px;
}

dialog#BrixxDialog input:focus {
  outline: 0;
}

dialog#BrixxDialog .dialog-header {
  margin: -17px;
  padding: 15px;
  background-color: #8ec2ff;
  font-size: 18px;
}

dialog#BrixxDialog hr {
  margin: 0px -15px 15px -15px;
  color: rgba(0, 0, 0, 0.114);
}

dialog#BrixxDialog .block-container {
  margin-bottom: 35px;
}

dialog#BrixxDialog .button-container {
  text-align: right;
}

.icon {
  width: 1.1em;
  height: 1.1em;
  vertical-align: -0.2em;
  margin-right: 2px;
}

.button {
  margin: 0;
  width: 50px;
  padding: 6px 0px;
  font-size: 16px;
  font-weight: normal;
  color: white;
  border: 1px solid #8ec2ff;
  border-radius: 3px;
  cursor: pointer;
  outline: none;
}

.button-primary,
.button-primary:active {
  background-color: #8ec2ff;
}

.button-primary:hover {
  background-color: #00a8ff;
}

.button-secondary,
.button-secondary:active {
  width: 80px;
  background-color: #8ec2ff;
}

.button-secondary:hover {
  background-color: #00a8ff;
}

@media screen and (max-width: 470px) {
  dialog#BrixxDialog {
    padding: 16px;
  }
}

@media screen and (max-width: 420px) {
  dialog#BrixxDialog {
    padding: 12px;
    max-width: 90%;
  }
}
